<script setup>
import { computed, ref } from 'vue'
import { reportState } from '../questionnaire.js'
const report=computed(()=>reportState.report)
const data=computed(()=>report.value?.summary)
const message=ref('')
const canExport=computed(()=>report.value && !reportState.stale)
function save(blob,filename){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadText(){save(new Blob([report.value.text],{type:'text/plain;charset=utf-8'}),'herhealth-summary.txt')}
function downloadPdf(){const bytes=Uint8Array.from(atob(report.value.pdf_base64),c=>c.charCodeAt(0));save(new Blob([bytes],{type:'application/pdf'}),report.value.pdf_filename)}
async function share(){try{if(navigator.share){await navigator.share({title:'HerHealth GP summary',text:report.value.text});message.value='Share sheet opened. Choose who to share with.'}else if(navigator.clipboard){await navigator.clipboard.writeText(report.value.text);message.value='Summary copied. You can paste it into a message to your clinician.'}else downloadText()}catch(error){if(error.name!=='AbortError')message.value='Sharing is unavailable. You can download your report instead.'}}
</script>
<template>
<div class="design-screen stack summary-page"><header class="page-header"><a class="icon-btn" href="#questions" aria-label="Back to questions">‹</a><div><h1>Summary</h1><p class="muted">For your healthcare professional</p></div></header>
<template v-if="report">
<p class="report-date">Prepared {{report.prepared_on}} · From your questionnaire answers</p>
<section v-if="reportState.stale" class="card no-print" role="status"><h2>Your answers have changed</h2><p class="muted">This is your previous report. Generate a new one before downloading or sharing.</p><a href="#questions" class="secondary full action-link">Update my report →</a></section>
<section v-if="data.concern" class="card"><h2>What I'd like help with</h2><p class="notes">{{data.concern}}</p></section>
<section v-for="alert in report.alerts.filter(a=>a.level!=='info')" :key="alert.key" class="card care-card" :class="{urgent:alert.level==='urgent'}"><span class="eyebrow">{{alert.level==='urgent'?'Urgent advice':'Discuss with your GP'}}</span><h2>{{alert.title}}</h2><p>{{alert.detail}}</p><ul v-if="alert.tests?.length"><li v-for="advice in alert.tests" :key="advice">{{advice}}</li></ul><a v-if="alert.link" :href="alert.link" target="_blank" rel="noopener noreferrer">{{alert.source}} ↗</a><small v-else>{{alert.source}}</small></section>
<section v-if="!data.flagged.length" class="card"><h2>Your health checks</h2><p class="muted">Your submitted answers did not match the backend's GP or urgent-care flags. This cannot rule out a condition. Speak with a healthcare professional if you are worried.</p></section>
<section class="card"><h2>Effect on daily life</h2><div v-if="data.impact" class="impact-score">{{data.impact[0]}}<small>/ 10</small></div><p v-else class="muted">Not rated</p><p class="muted">From your recent-health answers, reported on {{report.prepared_on}}.</p></section>
<section class="card"><h2>Your recent period</h2><div class="period-record" v-for="(period,index) in data.periods" :key="index"><dl><dt>First day</dt><dd>{{period[0]}}</dd><dt>Length</dt><dd>{{period[1] === 'ongoing'?'Ongoing':period[1]+' days'}}</dd><dt>Heaviest flow</dt><dd>{{period[2]}}</dd><dt>Worst pain</dt><dd>{{period[3]==='not recorded'?'Not recorded':period[3]+' / 10'}}</dd></dl></div><p v-if="!data.periods.length" class="muted">Period dates not recorded.</p><p class="muted">A cycle-length trend needs at least two periods. Sample calendar records are not included.</p></section>
<section class="card"><h2>Symptoms reported</h2><ul v-if="data.symptoms.length" class="plain-list"><li v-for="[label] in data.symptoms" :key="label">{{label}}</li></ul><p v-else class="muted">No symptoms selected.</p></section>
<section class="card"><h2>Medicines and solutions</h2><h3>Current medication</h3><p class="notes">{{data.medicines || 'None added'}}</p><h3>Solutions explored</h3><div v-if="data.tried.length" class="chip-row"><span v-for="solution in data.tried" :key="solution" class="pill">{{solution}}</span></div><p v-else class="muted">None selected</p><template v-if="data.tried_notes"><h3 class="treatment-heading">What helped or didn't</h3><p class="notes">{{data.tried_notes}}</p></template></section>
<section v-if="data.about.length" class="card"><h2>About me</h2><dl><template v-for="[label,value] in data.about" :key="label"><dt>{{label}}</dt><dd>{{value}}</dd></template></dl></section>
<section class="card"><h2>Questions for your appointment</h2><ul class="plain-list"><li v-for="question in data.questions" :key="question">{{question}}</li></ul><template v-if="report.follow_up_questions.length"><h3>Details you may want to discuss</h3><ul class="plain-list"><li v-for="question in report.follow_up_questions" :key="question">{{question}}</li></ul></template></section>
<div class="summary-actions no-print"><button class="primary full" :disabled="!canExport" @click="downloadPdf">Download GP report (PDF)</button><button class="secondary" :disabled="!canExport" @click="share">Share summary</button><button class="secondary" :disabled="!canExport" @click="downloadText">Download text copy</button><a href="#questions" class="text-button">Edit my answers</a><p v-if="message" role="status" class="notice">{{message}}</p></div>
<section class="card limitations"><h2>About this report</h2><p v-for="note in report.limitations" :key="note" class="muted">{{note}}</p><p class="muted">The report is kept only for this browser session. Reloading clears it.</p></section>
</template>
<section v-else class="card empty-summary"><h2>Let's prepare your GP report</h2><p class="muted">Answer a few questions about your recent period, symptoms and daily life. HerHealth will prepare a report you can review and download.</p><a href="#questions" class="primary full action-link">Answer the questions →</a></section>
</div>
</template>
<style scoped>
.summary-page{background:#f4ecdd!important}.page-header{justify-content:flex-start}.report-date{font-size:10px;color:#84785e;margin:0 20px}.notes{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.8;margin:8px 0 16px}.impact-score{font-size:30px;color:#85609d;font-weight:800}.impact-score small{font-size:14px;font-weight:400}.summary-actions{display:flex;flex-wrap:wrap;gap:10px;margin:0 14px}.summary-actions>.secondary{flex:1}.text-button{width:100%;padding:10px;font-size:12px;text-decoration:underline;text-align:center;color:#56318a}.care-card{border-left:4px solid #3552c9}.care-card.urgent{border-color:#b2284f;background:#fff4f5}.care-card.urgent .eyebrow{color:#b2284f}.care-card h2{margin-top:8px}.care-card p,.care-card li{font-size:12px;line-height:1.8}.care-card a,.care-card small{font-size:10px;color:#3552c9}.care-card a{text-decoration:underline}.plain-list{font-size:12px;line-height:1.8;padding-left:18px}.plain-list li{margin:6px 0}dl{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;font-size:12px;line-height:1.6}dt{color:#5a5f85}dd{margin:0;overflow-wrap:anywhere}.treatment-heading{margin-top:18px}.action-link{display:block;text-align:center}.empty-summary p{margin-bottom:20px}.limitations h2{font-size:13px}.limitations .muted{font-size:10px}.summary-actions button:disabled{opacity:.5;cursor:not-allowed}
</style>
